const body = $input.first().json.body || $input.first().json;
const { company_id, notification_type, recipients, priority, dedup_key } = body;

const isQuietHours = () => {
  const hour = new Date().getHours();
  return hour >= 22 || hour < 6;
};

const isCritical = priority === 'critical' || notification_type === 'sos';

return {
  json: {
    company_id,
    notification_type,
    priority: priority || 'normal',
    quiet_hours_active: isQuietHours() && !isCritical,
    delivery_deferred: isQuietHours() && !isCritical,
    dedup_key: dedup_key || `${company_id}:${notification_type}:${new Date().toISOString().slice(0, 10)}`,
    channels_attempted: [],
    delivery_status: isQuietHours() && !isCritical ? 'deferred' : 'sending',
    escalation_level: 0,
    generated_at: new Date().toISOString()
  }
};
